def accuracy(fn):
    out = fn(24)
    nodes, D = out["nodes"], out["derivative"]
    poly = nodes ** 5 - 3.0 * nodes ** 2 + 1.0
    exact = 5.0 * nodes ** 4 - 6.0 * nodes
